import 'dart:convert';
abstract interface class LocalStore { Future<void> write(String key,Object? value); Future<T?> read<T>(String key); Future<void> remove(String key); Future<void> clear(); }
class MemoryLocalStore implements LocalStore { final Map<String,Object?> _values={}; @override Future<void> write(String key,Object? value) async{_values[key]=jsonDecode(jsonEncode(value));} @override Future<T?> read<T>(String key) async=>_values[key] as T?; @override Future<void> remove(String key) async{_values.remove(key);} @override Future<void> clear() async{_values.clear();} }
abstract final class LocalKeys { static const session='session'; static const buyerPreferences='buyerPreferences'; static const searchRadius='searchRadius'; static const savedLocations='savedLocations'; static const watchlist='watchlist'; static const alertPreferences='alertPreferences'; static const recentSearches='recentSearches'; static const sellerDrafts='sellerDrafts'; static const language='language'; static const theme='theme'; }
